# Simulate continuous bounce with event solve
import numpy as np
def sim(t,y0,vy,g,F,e):
 y=y0;v=vy;dt=1.0
 for i in range(int(t)+1):
  if i==0:yield y
  else:
   # advance remaining
   rem=1
   while rem>1e-9:
    # time to hit floor if v>0 or currently above and descending
    if y<F-1e-9 or v<0:
     a=.5*g;b=v;c=y-F;disc=b*b-4*a*c
     if disc>=0:
      th=(-b+np.sqrt(disc))/(2*a)
     else: th=1e9
     if th<=rem:
      y=F;v=-e*(v+g*th);rem-=th
     else:
      y+=v*rem+.5*g*rem*rem;v+=g*rem;rem=0
    else:
     # at floor bounce upward
     v=-e*abs(v)
   yield y
for t in [12,13,15,22,32,33,40,48,55,61,73,82,95]:
 print(t,list(sim(t,21.75,.475,.745,86.3,.6))[-1])
